-- Termine endgültig löschen, mit lückenlosen Auftragsnummern.
--
-- Die Auftragsnummer (termine.nummer) zählt fortlaufend ab 1001. Wird ein Termin gelöscht, rücken alle
-- späteren Nummern um eins nach, und der Zähler macht hinter der höchsten Nummer weiter. Aus 1001, 1002,
-- 1003 wird nach dem Löschen von 1002 also 1001, 1002, und der nächste Termin bekommt 1003.
--
-- Dafür darf die Spalte nicht mehr „generated always“ sein (das verbietet jedes Ändern der Nummer),
-- sondern „generated by default“. Neue Termine bekommen ihre Nummer weiter automatisch.
--
-- Was mit dem Termin verschwindet: Fotos (on delete cascade). Verlauf, Fotodateien und Kalendereintrag
-- räumt die App auf (src/lib/termine.ts, loeschen). Rechnungen und Kostenvoranschläge bleiben und verlieren
-- nur den Verweis (on delete set null): Eine gestellte Rechnung ist ein Buchungsbeleg und bleibt.

alter table public.termine alter column nummer set generated by default;

create function public.termin_loeschen(p_id uuid)
returns integer language plpgsql security definer set search_path = '' as $$
declare
  v_nummer integer;
begin
  -- Dieselbe Sperre wie beim Anlegen: Solange gelöscht und nachnummeriert wird, vergibt niemand eine Nummer.
  perform pg_advisory_xact_lock(hashtextextended('termine', 0));
  delete from public.termine where id = p_id returning nummer into v_nummer;
  if not found then raise exception 'NICHT_GEFUNDEN' using errcode = 'P0001'; end if;

  -- In zwei Schritten über negative Zahlen: Rückt man direkt um eins nach, stößt je nach Reihenfolge der
  -- Zeilen eine Nummer kurz auf die noch belegte nächste und die Eindeutigkeit schlägt an.
  update public.termine set nummer = -nummer where nummer > v_nummer;
  update public.termine set nummer = -nummer - 1 where nummer < 0;

  -- Zähler hinter die höchste Nummer setzen (ohne Termine wieder auf 1001).
  perform setval(pg_get_serial_sequence('public.termine', 'nummer'), coalesce((select max(nummer) from public.termine), 1000));
  return v_nummer;
end;
$$;

revoke execute on function public.termin_loeschen(uuid) from public, anon, authenticated;
grant execute on function public.termin_loeschen(uuid) to service_role;
